def test_with_span_callable_and_context_manager(
    setup: tuple[otel_trace.Tracer, InMemorySpanExporter],
) -> None:
    tracer, exporter = setup
    result = with_span(
        "outer",
        lambda span: span.get_span_context().trace_id,
        attributes={"a": 1},
        kind="server",
        tracer=tracer,
    )
    assert isinstance(result, int)
    linked = exporter.spans[0]
    with with_span(
        "cm",
        tracer=tracer,
        links=[otel_trace.SpanContext(int(linked.trace_id, 16), int(linked.span_id, 16), False)],
    ) as span:
        assert current_span() is span
        assert current_trace_id() == format(span.get_span_context().trace_id, "032x")
        assert current_span_id() == format(span.get_span_context().span_id, "016x")
        assert trace_fields() == {"trace_id": current_trace_id(), "span_id": current_span_id()}
        add_event("checkpoint", {"n": 1})
    outer, cm = exporter.spans
    assert outer.kind == "server"
    assert outer.attributes == {"a": 1}
    assert cm.links[0].span_id == linked.span_id
    assert cm.events[0].name == "checkpoint"
    assert current_trace_id() is None
    assert current_span_id() is None
    assert trace_fields() == {}


def test_with_span_records_errors(setup: tuple[otel_trace.Tracer, InMemorySpanExporter]) -> None:
    tracer, exporter = setup
    with pytest.raises(ValueError, match="bad"), with_span("fails", tracer=tracer):
        raise ValueError("bad")
    with pytest.raises(KeyError):
        with_span("fails2", lambda span: {}["missing"], tracer=tracer)
    first, second = exporter.spans
    assert first.status.code == "error"
    assert first.status.message == "ValueError: bad"
    assert first.events[0].name == "exception"
    assert second.status.message is not None


