def test_traced_sync(setup: tuple[otel_trace.Tracer, InMemorySpanExporter]) -> None:
    tracer, exporter = setup

    @traced(tracer=tracer, attributes={"x": 1}, kind="client")
    def add(a: int, b: int) -> int:
        return a + b

    @traced("custom-name", tracer=tracer)
    def boom() -> None:
        raise RuntimeError("no")

    assert add(1, 2) == 3
    assert add.__name__ == "add"
    with pytest.raises(RuntimeError):
        boom()
    names = [s.name for s in exporter.spans]
    assert names[0].endswith("add")
    assert names[1] == "custom-name"
    assert exporter.spans[0].kind == "client"
    assert exporter.spans[1].status.code == "error"


