def test_record_exception_and_set_error(
    setup: tuple[otel_trace.Tracer, InMemorySpanExporter],
) -> None:
    tracer, exporter = setup
    with with_span("a", tracer=tracer):
        record_exception(ValueError("seen"), {"handled": True})
    with with_span("b", tracer=tracer):
        set_error("plain message")
    with with_span("c", tracer=tracer):
        set_error(RuntimeError())
    a, b, c = exporter.spans
    assert a.status.code == "unset"
    assert a.events[0].attributes["handled"] is True
    assert (b.status.code, b.status.message) == ("error", "plain message")
    assert b.events == ()
    assert c.status.message == "RuntimeError"
    # without an active span these are no-ops
    add_event("x")
    record_exception(ValueError("x"))
    set_error("x")
    assert StatusCode.ERROR.name == "ERROR"


def test_inject_and_extract(setup: tuple[otel_trace.Tracer, InMemorySpanExporter]) -> None:
    tracer, _ = setup
    with tracer.start_as_current_span("parent") as span:
        carrier = inject(propagator=PROPAGATOR)
        assert carrier["traceparent"].split("-")[1] == format(
            span.get_span_context().trace_id, "032x"
        )
        headers: dict[str, str] = {"x": "y"}
        assert inject_headers(headers, propagator=PROPAGATOR) is headers
        assert "traceparent" in headers
    context = extract(carrier, propagator=PROPAGATOR)
    remote = otel_trace.get_current_span(context).get_span_context()
    assert remote.is_remote
    assert remote.trace_id == span.get_span_context().trace_id
    assert isinstance(inject(), dict)  # the global propagator works too
    assert extract({}) is not None


def test_extract_headers_case_insensitive_and_bytes() -> None:
    context = extract_headers(
        {"TraceParent": TRACEPARENT, "Baggage": "user=bob"}, propagator=PROPAGATOR
    )
    span_context = otel_trace.get_current_span(context).get_span_context()
    assert format(span_context.trace_id, "032x") == "4bf92f3577b34da6a3ce929d0e0e4736"
    assert baggage.get_baggage("user", context) == "bob"
    from_bytes = extract_headers([(b"traceparent", TRACEPARENT.encode())], propagator=PROPAGATOR)
    assert otel_trace.get_current_span(from_bytes).get_span_context().span_id == 0x00F067AA0BA902B7
    assert extract_headers({}).get("x") is None
    assert normalize_headers([("A", "1"), (b"a", b"2")]) == {"a": ["1", "2"]}


